    await expect(ctx.sessionReferenceResolver.listCandidates(fakeAgent(target), 'LATEST', 1)).resolves.toEqual([
      { sessionId: SessionId('same-later'), label: 'Latest title', cwd: '/same', createdAt: 25 },
